package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// thresholdsConfigPathEnv 可选地覆盖阈值配置的位置，供工作目录不在仓库根目录时使用。
const thresholdsConfigPathEnv = "INVENTORY_THRESHOLDS_CONFIG"

// thresholdsConfigName 是配置相对于仓库根目录的路径。
const thresholdsConfigName = "config/thresholds.json"

// loadThresholdOverrides 读取 config/thresholds.json 里的按仓库覆盖值。
//
// 每次调用都重新读盘，所以运维改完配置无需重新构建或重启即可生效。
// 文件缺失、JSON 非法或值不合法时返回空覆盖，所有仓库回退到
// DefaultLowStockThreshold。
func loadThresholdOverrides() map[string]int {
	path, ok := thresholdsConfigPath()
	if !ok {
		return nil
	}
	return loadThresholdOverridesFrom(path)
}

func loadThresholdOverridesFrom(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	overrides := map[string]int{}
	if err := json.Unmarshal(data, &overrides); err != nil {
		return nil
	}
	for warehouse, threshold := range overrides {
		if threshold < 0 {
			delete(overrides, warehouse)
		}
	}
	return overrides
}

// thresholdsConfigPath 返回要读取的配置文件。
//
// INVENTORY_THRESHOLDS_CONFIG 优先；否则从工作目录向上逐层查找
// config/thresholds.json，到含 go.mod 的模块根目录为止。这样从仓库根目录、
// 从 inventory/ 下跑 `go test`、以及从部署目录运行都能找到同一份配置。
func thresholdsConfigPath() (string, bool) {
	if path := os.Getenv(thresholdsConfigPathEnv); path != "" {
		return path, true
	}
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		candidate := filepath.Join(dir, thresholdsConfigName)
		if _, err := os.Stat(candidate); err == nil {
			return candidate, true
		}
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return "", false
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// thresholdFor 返回仓库的阈值：有覆盖用覆盖值，否则用默认值。
func thresholdFor(overrides map[string]int, warehouse string) int {
	if threshold, ok := overrides[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

