package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

func writeThresholdsConfig(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("写入配置失败: %v", err)
	}
}

func TestConfiguredWarehouseUsesItsThreshold(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	writeThresholdsConfig(t, path, `{"xian": 10}`)
	t.Setenv(thresholdsConfigPathEnv, path)

	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 10", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	writeThresholdsConfig(t, path, `{"xian": 10}`)
	t.Setenv(thresholdsConfigPathEnv, path)

	if !IsLowStock("xian", 9) {
		t.Fatal("低于配置阈值应当算低库存")
	}
	if IsLowStock("xian", 10) {
		t.Fatal("等于配置阈值不算低库存（严格小于）")
	}
}

func TestConfigEditTakesEffectWithoutRestart(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	t.Setenv(thresholdsConfigPathEnv, path)

	writeThresholdsConfig(t, path, `{"xian": 10}`)
	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("第一次读取 = %d, 期望 10", got)
	}

	// 不重启进程、不重新构建，直接改文件后下一次查询就应看到新值。
	writeThresholdsConfig(t, path, `{"xian": 2}`)
	if got := LowStockThreshold("xian"); got != 2 {
		t.Fatalf("改配置后 = %d, 期望立即变为 2", got)
	}
}

func TestLowStockWarehousesUsesConfiguredThresholds(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	writeThresholdsConfig(t, path, `{"beijing": 20}`)
	t.Setenv(thresholdsConfigPathEnv, path)

	// beijing 被上面调高了阈值所以算低库存；chengdu 用默认 5，15 不算。
	got := LowStockWarehouses(map[string]int{"beijing": 15, "chengdu": 15})
	want := []string{"beijing"}
	if len(got) != len(want) || got[0] != want[0] {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
}

func TestInvalidConfigFallsBackToDefault(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	t.Setenv(thresholdsConfigPathEnv, path)

	cases := []struct {
		name    string
		content string
	}{
		{"JSON 非法", `{not json`},
		{"类型不对", `{"xian": "10"}`},
		{"负数被忽略", `{"xian": -1}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			writeThresholdsConfig(t, path, tc.content)
			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(xian) = %d, 期望回退默认值 %d",
					got, DefaultLowStockThreshold)
			}
		})
	}

	if err := os.Remove(path); err != nil {
		t.Fatalf("删除配置失败: %v", err)
	}
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置缺失应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}
